import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.util.Iterator;

public class Main {
    public static void main(String[] args) throws Exception {
        Selector selector = Selector.open();
        ServerSocketChannel server = ServerSocketChannel.open();
        server.bind(new InetSocketAddress("127.0.0.1", 0));
        server.configureBlocking(false);
        server.register(selector, SelectionKey.OP_ACCEPT);
        int port = ((InetSocketAddress) server.getLocalAddress()).getPort();

        SocketChannel client = SocketChannel.open(new InetSocketAddress("127.0.0.1", port));

        // step 1: accept is ready
        int n1 = selector.select(2000);
        System.out.println("step1 select() returned    : " + n1);
        Iterator<SelectionKey> it = selector.selectedKeys().iterator();
        SocketChannel accepted = null;
        while (it.hasNext()) {
            SelectionKey key = it.next();
            it.remove();                     // MUST remove, otherwise the event repeats
            if (key.isAcceptable()) {
                accepted = server.accept();
                accepted.configureBlocking(false);
                accepted.register(selector, SelectionKey.OP_READ);
            }
        }
        System.out.println("accepted a connection      : " + (accepted != null));

        // step 2: client sends, then read is ready
        String msg = "ping";
        client.write(ByteBuffer.wrap(msg.getBytes(StandardCharsets.US_ASCII)));
        int n2 = selector.select(2000);
        System.out.println("step2 select() returned    : " + n2);
        String got = "";
        it = selector.selectedKeys().iterator();
        while (it.hasNext()) {
            SelectionKey key = it.next();
            it.remove();
            if (key.isReadable()) {
                SocketChannel ch = (SocketChannel) key.channel();
                ByteBuffer buf = ByteBuffer.allocate(16);
                ch.read(buf);
                buf.flip();
                got = new String(buf.array(), 0, buf.limit(), StandardCharsets.US_ASCII);
            }
        }
        System.out.println("server received            : " + got);
        System.out.println("echo matches               : " + msg.equals(got));
        System.out.println("selectedKeys cleared after remove : " + (selector.selectedKeys().isEmpty()));

        // step 3: unregister OP_WRITE would spin forever, so we only ever ask for READ here
        System.out.println("only OP_ACCEPT / OP_READ were registered (OP_WRITE is almost always ready)");

        client.close();
        accepted.close();
        server.close();
        selector.close();
    }
}
